// Locale plumbing is generated by scripts/build-i18n.js. These assertions are
// STRUCTURAL (never translated prose) so they hold for every locale: the
// English-text assertions live in the English-only specs.
const { test, expect } = require('@playwright/test');
const AxeBuilder = require('@axe-core/playwright').default;

const ORIGIN = 'https://vitorschiavo.dev';

const LOCALES = [
  { lang: 'en', label: 'EN' },
  { lang: 'pt-BR', label: 'PT' },
  { lang: 'es', label: 'ES' },
];

const PAGES = [
  { name: 'home', paths: { en: '/', 'pt-BR': '/pt/', es: '/es/' } },
  { name: 'resume', paths: { en: '/resume.html', 'pt-BR': '/pt/resume.html', es: '/es/resume.html' } },
];

for (const pg of PAGES) {
  for (const loc of LOCALES) {
    const path = pg.paths[loc.lang];

    test.describe(`${pg.name} · ${loc.lang}`, () => {
      test('document lang, single h1 and self-referencing canonical', async ({ page }) => {
        await page.goto(path);
        await expect(page.locator('html')).toHaveAttribute('lang', loc.lang);
        await expect(page.locator('h1')).toHaveCount(1);
        await expect(page.locator('link[rel="canonical"]')).toHaveAttribute('href', ORIGIN + path);
      });

      test('reciprocal hreflang alternates plus x-default', async ({ page }) => {
        await page.goto(path);
        for (const l of LOCALES) {
          await expect(page.locator(`link[rel="alternate"][hreflang="${l.lang}"]`))
            .toHaveAttribute('href', ORIGIN + pg.paths[l.lang]);
        }
        await expect(page.locator('link[rel="alternate"][hreflang="x-default"]'))
          .toHaveAttribute('href', ORIGIN + pg.paths.en);
      });

      test('language switcher marks the current locale and links to the siblings', async ({ page }) => {
        await page.goto(path);
        await expect(page.locator('.lang-switcher__item--current').first()).toHaveText(loc.label);
        for (const l of LOCALES) {
          if (l.lang === loc.lang) continue;
          await expect(page.locator(`.lang-switcher a[hreflang="${l.lang}"]`).first())
            .toHaveAttribute('href', pg.paths[l.lang]);
        }
      });

      test('no critical accessibility violations', async ({ page }) => {
        await page.goto(path);
        await page.emulateMedia({ reducedMotion: 'reduce' });
        const results = await new AxeBuilder({ page }).withTags(['wcag2a', 'wcag2aa']).analyze();
        expect(results.violations).toEqual([]);
      });

      test('every internal link resolves (no dead links)', async ({ page }) => {
        await page.goto(path);
        const hrefs = await page.$$eval('a[href^="/"]', els => els.map(a => a.getAttribute('href')));
        const unique = [...new Set(hrefs.map(h => h.split('#')[0]).filter(Boolean))];
        for (const href of unique) {
          const res = await page.request.get(href);
          expect(res.status(), `${href} should resolve`).toBe(200);
        }
      });

      if (pg.name === 'home') {
        test('runtime I18N strings render in the page language', async ({ page }) => {
          // The theme-toggle aria-label is set by script.js from the I18N map
          // keyed on <html lang>; a missing/renamed key would surface here.
          const themeToDark = { en: 'Switch to dark theme', 'pt-BR': 'Mudar para o tema escuro', es: 'Cambiar al tema oscuro' };
          await page.goto(path);
          await page.locator('#themeToggle').click(); // dark -> light; JS rewrites the label
          await expect(page.locator('#themeToggle')).toHaveAttribute('aria-label', themeToDark[loc.lang]);
        });

        test('every platform-explorer view yields a resolving case link', async ({ page }) => {
          await page.goto(path);
          // Exercise all three views: each view's link lives only in the JSON block
          // until clicked, so a bad slug in one would 404 without this loop.
          for (const view of ['delivery', 'reliability', 'efficiency']) {
            await page.locator(`[data-platform-view="${view}"]`).click();
            const href = await page.locator('#platform-story-link').getAttribute('href');
            // Locale-prefixed once that case is translated, else the English fallback.
            expect(href, `${view} link shape`).toMatch(/^(\/(?:pt|es))?\/cases\/[a-z0-9-]+\/$/);
            expect((await page.request.get(href)).status(), `${view} -> ${href}`).toBe(200);
          }
        });
      }
    });
  }
}
